// NOTE: Rotating text animation component with smooth stagger transitions
// Based on React Bits implementation
'use client';

import { AnimatePresence, domAnimation, LazyMotion, m } from 'motion/react';
import { useCallback, useEffect, useMemo, useState } from 'react';

import { cn } from '@/lib/utils';

interface RotatingTextProps {
  /** Array of texts to rotate through */
  texts: string[];
  /** ClassName applied to the main container */
  mainClassName?: string;
  /** Direction to stagger the letter animations from */
  staggerFrom?: 'first' | 'last' | 'center';
  /** Initial animation state for each letter */
  initial?: object;
  /** Animate state for each letter */
  animate?: object;
  /** Exit animation state for each letter */
  exit?: object;
  /** Duration between each letter animation in stagger */
  staggerDuration?: number;
  /** ClassName applied to each letter wrapper */
  splitLevelClassName?: string;
  /** Transition configuration for letter animations */
  transition?: object;
  /** Interval in ms between text rotations */
  rotationInterval?: number;
}

export default function RotatingText({
  texts,
  mainClassName = '',
  staggerFrom = 'first',
  initial = { y: '100%', opacity: 0 },
  animate = { y: 0, opacity: 1 },
  exit = { y: '-120%', opacity: 0 },
  staggerDuration = 0.025,
  splitLevelClassName = '',
  transition = { type: 'spring', damping: 30, stiffness: 400 },
  rotationInterval = 2000,
}: Readonly<RotatingTextProps>) {
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex((prevIndex) => (prevIndex + 1) % texts.length);
    }, rotationInterval);

    return () => clearInterval(interval);
  }, [texts.length, rotationInterval]);

  // NOTE: Split text into characters using proper Unicode segmentation
  const splitIntoCharacters = useCallback((text: string): string[] => {
    if (typeof Intl !== 'undefined' && Intl.Segmenter) {
      const segmenter = new Intl.Segmenter('en', { granularity: 'grapheme' });
      return Array.from(segmenter.segment(text), (segment) => segment.segment);
    }
    return [...text];
  }, []);

  // NOTE: Split current text into words and characters
  const elements = useMemo(() => {
    const currentText = texts[currentIndex];
    const words = currentText.split(' ');
    return words.map((word, i) => ({
      characters: splitIntoCharacters(word),
      needsSpace: i !== words.length - 1,
    }));
  }, [texts, currentIndex, splitIntoCharacters]);

  // NOTE: Calculate total number of characters for stagger
  const totalChars = useMemo(() => {
    return elements.reduce((acc, word) => acc + word.characters.length, 0);
  }, [elements]);

  // NOTE: Calculate stagger delay based on direction
  const getStaggerDelay = useCallback(
    (charIndex: number) => {
      const total = totalChars;
      switch (staggerFrom) {
        case 'last': {
          return (total - 1 - charIndex) * staggerDuration;
        }
        case 'center': {
          return Math.abs(Math.floor(total / 2) - charIndex) * staggerDuration;
        }
        default: {
          return charIndex * staggerDuration;
        }
      }
    },
    [staggerFrom, staggerDuration, totalChars]
  );

  let charCounter = 0;

  return (
    <LazyMotion features={domAnimation}>
      <span className={cn('inline-flex', mainClassName)}>
        <AnimatePresence mode="wait" initial={false}>
          <m.span key={currentIndex} className="inline-flex flex-wrap">
            {elements.map((wordData, wordIndex) => (
              <span key={wordIndex} className="inline-flex">
                {wordData.characters.map((char) => {
                  const globalCharIndex = charCounter++;
                  return (
                    <m.span
                      key={`${currentIndex}-${globalCharIndex}`}
                      className={cn('inline-block', splitLevelClassName)}
                      /* eslint-disable @typescript-eslint/no-explicit-any */
                      initial={initial as any}
                      animate={animate as any}
                      exit={exit as any}
                      transition={
                        {
                          ...transition,
                          delay: getStaggerDelay(globalCharIndex),
                        } as any
                      }
                      /* eslint-enable @typescript-eslint/no-explicit-any */
                    >
                      {char}
                    </m.span>
                  );
                })}
                {wordData.needsSpace && <span>&nbsp;</span>}
              </span>
            ))}
          </m.span>
        </AnimatePresence>
      </span>
    </LazyMotion>
  );
}
